char* safe_buffer_copy(const char* src, size_t max_len) {
    if (!src || max_len == 0) return NULL;
    size_t len = strnlen(src, max_len);
    char* dest = (char*)malloc(len + 1);
    if (!dest) return NULL;
    memcpy(dest, src, len);
    dest[len] = '\0';
    return dest;
}

int safe_int_divide(int a, int b, int* out_res) {
    if (!out_res || b == 0) return -1;
    if (a == INT_MIN && b == -1) return -2;
    *out_res = a / b;
    return 0;
}

int safe_array_lookup(const int* arr, size_t size, size_t index, int* out_val) {
    if (!arr || !out_val || index >= size) return -1;
    *out_val = arr[index];
    return 0;
}

char* safe_file_read_line(FILE* fp, size_t max_bytes) {
    if (!fp || max_bytes == 0) return NULL;
    char* buf = (char*)malloc(max_bytes + 1);
    if (!buf) return NULL;
    if (!fgets(buf, (int)(max_bytes + 1), fp)) {
        free(buf);
        return NULL;
    }
    return buf;
}

char* safe_str_trim(char* s) {
    if (!s) return NULL;
    while (isspace((unsigned char)*s)) s++;
    if (*s == 0) return s;
    char* end = s + strlen(s) - 1;
    while (end > s && isspace((unsigned char)*end)) end--;
    end[1] = '\0';
    return s;
}

double** safe_matrix_create(size_t rows, size_t cols) {
    if (rows == 0 || cols == 0) return NULL;
    double** mat = (double**)malloc(rows * sizeof(double*));
    if (!mat) return NULL;
    for (size_t i = 0; i < rows; ++i) {
        mat[i] = (double*)calloc(cols, sizeof(double));
        if (!mat[i]) {
            for (size_t j = 0; j < i; ++j) free(mat[j]);
            free(mat);
            return NULL;
        }
    }
    return mat;
}

