use std::sync::atomic::{AtomicUsize, Ordering};

pub struct AtomicCounter {
    val: AtomicUsize,
}

impl AtomicCounter {
    pub fn new(init: usize) -> Self {
        Self { val: AtomicUsize::new(init) }
    }
    pub fn inc(&self) -> usize {
        self.val.fetch_add(1, Ordering::SeqCst)
    }
    pub fn get(&self) -> usize {
        self.val.load(Ordering::SeqCst)
    }
}

use std::collections::HashMap;
use std::sync::{Arc, RwLock};

pub struct ThreadSafeMap<K, V> {
    inner: Arc<RwLock<HashMap<K, V>>>,
}

impl<K: std::hash::Hash + Eq + Clone, V: Clone> ThreadSafeMap<K, V> {
    pub fn new() -> Self {
        Self { inner: Arc::new(RwLock::new(HashMap::new())) }
    }
    pub fn insert(&self, k: K, v: V) {
        self.inner.write().unwrap().insert(k, v);
    }
    pub fn get(&self, k: &K) -> Option<V> {
        self.inner.read().unwrap().get(k).cloned()
    }
}

