public static async Task<T> ExecuteWithTimeoutAsync<T>(Func<CancellationToken, Task<T>> action, TimeSpan timeout) {
    using var cts = new CancellationTokenSource(timeout);
    try {
        return await action(cts.Token).ConfigureAwait(false);
    } catch (OperationCanceledException) when (!cts.IsCancellationRequested) {
        throw new TimeoutException($"Action timed out after {timeout.TotalMilliseconds}ms");
    }
}

